import{z as s,x as n,o as l,c as d,q as o,j as A,D as e,d as i,s as r,S as E}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"端到端语音对话","description":"","frontmatter":{"title":"端到端语音对话","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/e2e-speech-dialogue.md","filePath":"llm/e2e-speech-dialogue.md","lastUpdated":1791413859000}'),p={name:"llm/e2e-speech-dialogue.md"};function T(h,a,m,c,_,B){const t=n("Mermaid");return l(),d("div",null,[a[2]||(a[2]=o('<h1 id="端到端语音对话" tabindex="-1">端到端语音对话 <a class="header-anchor" href="#端到端语音对话" aria-label="Permalink to &quot;端到端语音对话&quot;">​</a></h1><div class="epigraph"><p>ASR 与 TTS 把对话钉在转写上。韵律、重叠、笑声过不了文字，延迟却过了三跳。</p><footer>—— 对照 SpeechGPT、GPT-4o 语音、Qwen2-Audio 等语音进 / 语音出系统；双工细节见 [Moshi](/llm/full-duplex-speech)</footer></div><p><a href="/llm/full-duplex-speech">上一课</a>给出同时听说的栈。缺口是系统切法：要不要以文本为必经接口。级联（ASR–LLM–TTS）可复用文本 LLM 与 <a href="/llm/valle-tts">VALL-E</a> 式合成；端到端把声学 token 直接送进同一骨干。后课音乐默认：另一条长程音频生成，目标不是对话轮次。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>级联的好处是文本可审核、可接工具。坏处是：识别错误不可逆、韵律在转写里消失、三模型延迟。端到端把用户 codec 当视觉前缀的音频版——连续或离散声学 token 进 LLM，输出可以是文本、声学码或两者。Qwen2-Audio 等强调语音理解；GPT-4o 类产品强调语音出也走同一模型。Mini-Omni / LLaMA-Omni 探索冻结文本 LLM、加语音头。</p>',5)),(l(),A(E,null,{default:e(()=>[r(t,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E7%94%A8%E6%88%B7%E8%AF%AD%E9%9F%B3%22%5D%20--%3E%20CAS%5B%22%E7%BA%A7%E8%81%94%E8%B7%AF%E7%BA%BF%22%5D%0A%20%20CAS%20--%3E%20ASR%5B%22ASR%20%E8%BD%AC%E5%86%99%22%5D%0A%20%20ASR%20--%3E%20TXT%5B%22%E6%96%87%E6%9C%AC%20LLM%22%5D%0A%20%20TXT%20--%3E%20TTS%5B%22TTS%20%E5%90%88%E6%88%90%22%5D%0A%20%20TTS%20--%3E%20OUT%5B%22%E5%9B%9E%E5%A4%8D%E8%AF%AD%E9%9F%B3%22%5D%0A%20%20IN%20--%3E%20E2E%5B%22%E7%AB%AF%E5%88%B0%E7%AB%AF%E8%B7%AF%E7%BA%BF%22%5D%0A%20%20E2E%20--%3E%20LM%5B%22%E8%AF%AD%E9%9F%B3-%E8%AF%AD%E8%A8%80%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20LM%20--%3E%20OUT%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<p><span class="marginnote">「ASR」是把语音转成文字的识别模型，「TTS」是把文字念成语音的合成模型。级联系统像带两个翻译的会面：每翻译一次多一点延迟和失真，而且 ASR 认错一个词，后面全部照错、无法回头——这就是「识别错误不可逆」。</span></p><p>与 <a href="/llm/llava-projector">LLaVA 投影器</a> 同构：浅投影把编码器特征送进词槽，只是编码器从 <a href="/llm/vit-as-encoder">ViT</a> 换成音频编码器。</p><p><span class="marginnote">没有文本中间层时，安全与工具调用要另接：或并行出文本流（Moshi 内心独白），或对声学做事后 ASR。完全无文本不可审计。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选接口：级联、语音-in 文本-out、真语音-in 语音-out。训练混合 ASR、口语指令、语音回答。评测：内容 WER/任务成功率、韵律与打断、延迟分位数。不要只用文本 MMLU 冒充语音对话能力。</p><p><span class="marginnote">常见误区：拿 MMLU 高分当语音对话能力强。文本考试不考「有没有听懂打断、语气对不对、回应有没有超过人等待的耐心」，语音系统要单独看内容 WER、任务成功率、打断行为与延迟分位数。</span></p>',6)),(l(),A(E,null,{default:e(()=>[r(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20WAV%5B%22%E7%94%A8%E6%88%B7%E8%AF%AD%E9%9F%B3%22%5D%20--%3E%20E2E%5B%22%E8%AF%AD%E9%9F%B3-%E8%AF%AD%E8%A8%80%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20E2E%20--%3E%20TOUT%5B%22%E6%96%87%E6%9C%AC%E5%8F%AF%E9%80%89%22%5D%0A%20%20E2E%20--%3E%20AOUT%5B%22%E8%AF%AD%E9%9F%B3%E5%87%BA%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>端到端让韵律条件直达生成，不必从文字恢复。代价是语言能力受语音数据覆盖限制：罕见实体仍常靠内部文本流。因此许多「端到端」实际是多流，而不是消灭文字。</p><p><span class="marginnote">直觉类比：「韵律」是「怎么说的」——抑扬顿挫、语速、笑意；文字只记「说了什么」。级联把「怎么说」丢在 ASR 门口，TTS 只能按默认语气重新演一遍；端到端让模型直接听原声，语气得以延续。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>对话语音的时长与结构不同于歌曲。下一课用 codec AR 做音乐。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>端到端语音对话去掉必经 ASR/TTS，换延迟与韵律。</li><li>可审计性通常还要并行文本流。</li><li>投影音频编码器进 LLM 与 LLaVA 浅桥同构。</li><li>出处：SpeechGPT；Qwen2-Audio；Moshi；产品侧 GPT-4o 语音。</li></ul>',7))])}const D=s(p,[["render",T]]);export{S as __pageData,D as default};
